function solve(arr) {
  const res = [];
  let levelSize = 1, idx = 0;
  while (idx < arr.length) {
    const slice = arr.slice(idx, idx + levelSize).reverse();
    res.push(...slice);
    idx += levelSize;
    levelSize *= 2;
  }
  return res;
}

function solve(arr) {
  const res = [];
  for (let d = 0; (1 << d) - 1 < arr.length; d++) {
    const start = (1 << d) - 1;
    res.push(...arr.slice(start, start + (1 << d)).reverse());
  }
  return res;
}

